import SwiftUI
import UIKit
struct ExportView: View { @EnvironmentObject private var appState: AppState; @State private var shareURL: URL?; @State private var exported=false; var body: some View { NavigationStack { VStack(spacing:18){ ResumePreviewView(); Button("Export as PDF"){exportPDF()}.buttonStyle(.borderedProminent).tint(DS.ColorToken.primary); if exported { Text("PDF exported").font(DS.FontToken.caption).padding(8).background(Capsule().fill(DS.ColorToken.surfaceOffset)) } }.navigationTitle("Preview").navigationBarTitleDisplayMode(.inline).sheet(item:$shareURL){ShareSheet(url:$0)} } }
    private func exportPDF(){ let page=CGRect(x:0,y:0,width:595,height:842); let renderer=UIGraphicsPDFRenderer(bounds:page); let data=renderer.pdfData{context in context.beginPage(); let text=NSMutableAttributedString(string:appState.activeResume.name+"\n\n",attributes:[.font:UIFont.boldSystemFont(ofSize:24)]); for section in appState.activeResume.sections.filter({$0.isVisible}).sorted(by:{$0.order<$1.order}) { text.append(NSAttributedString(string:section.title.uppercased()+"\n",attributes:[.font:UIFont.boldSystemFont(ofSize:12)])); for field in section.fields { text.append(NSAttributedString(string:"\(field.label): \(field.value)\n",attributes:[.font:UIFont.systemFont(ofSize:10)])) }; text.append(NSAttributedString(string:"\n")) }; text.draw(in:page.insetBy(dx:36,dy:36)) }; let url=FileManager.default.temporaryDirectory.appendingPathComponent("ResumeMaster.pdf"); try? data.write(to:url); shareURL=url; withAnimation(.badgeAppear){exported=true} }
}
struct ShareSheet: UIViewControllerRepresentable { let url: URL; func makeUIViewController(context: Context)->UIActivityViewController{UIActivityViewController(activityItems:[url],applicationActivities:nil)}; func updateUIViewController(_ controller:UIActivityViewController,context:Context){} }
extension URL: Identifiable { public var id: String { absoluteString } }
